/* One cheap request tells us exactly how many pages this run needs, and
 * x-wp-total goes straight into the run log. Incremental: only posts modified
 * since our last clean run, minus an hour of overlap for clock skew. */
const s = $json;
const cfg = s.config || {};
const since = s.last_success_at
  ? new Date(new Date(s.last_success_at).getTime() - 36e5).toISOString().slice(0, 19)
  : null;
const qs = new URLSearchParams({ per_page: '1', _fields: 'id', orderby: 'modified', order: 'desc' });
if (since) qs.set('modified_after', since);
if (Array.isArray(cfg.exclude_categories) && cfg.exclude_categories.length)
  qs.set('categories_exclude', cfg.exclude_categories.join(','));
return { json: { source: s, probe_url: `${s.base_url}/posts?${qs.toString()}` } };

/* W02 · WordPress REST ingest — turn one `sources` row + the probe response
 * into an explicit list of page URLs. Explicit paging beats the HTTP node's
 * built-in pagination here: WP returns HTTP 400 past the last page, and we
 * want the x-wp-totalpages header to decide, not an error. */
const src   = $('Loop Sources').first().json;
const probe = $input.first().json;

const cfg      = src.config || {};
const perPage  = cfg.per_page || 100;
const headers  = probe.headers || {};
const totalPages = Math.min(parseInt(headers['x-wp-totalpages'] || '1', 10) || 1, cfg.max_pages || 20);
const total      = parseInt(headers['x-wp-total'] || '0', 10) || 0;

// Only ask for the fields we actually store. class_list carries country-* and
// funding_type-* (those taxonomies are not exposed as REST routes).
const FIELDS = ['id','slug','link','date_gmt','modified_gmt','title','excerpt',
                'content','categories','class_list','di_urgency',
                'yoast_head_json','jetpack_featured_media_url'].join(',');

// Incremental: only posts touched since our last clean run, minus a safety lap.
const since = src.last_success_at
  ? new Date(new Date(src.last_success_at).getTime() - 36e5).toISOString().slice(0, 19)
  : null;

const items = [];
for (let page = 1; page <= totalPages; page++) {
  const qs = new URLSearchParams({
    per_page: String(perPage), page: String(page),
    orderby: 'modified', order: 'desc', _fields: FIELDS,
  });
  if (since) qs.set('modified_after', since);
  if (Array.isArray(cfg.exclude_categories) && cfg.exclude_categories.length)
    qs.set('categories_exclude', cfg.exclude_categories.join(','));
  items.push({ json: {
    source_slug: src.slug,
    page,
    total_pages: totalPages,
    total_items: total,
    incremental: Boolean(since),
    url: `${src.base_url}/posts?${qs.toString()}`,
  }});
}
if (!items.length) items.push({ json: { source_slug: src.slug, page: 0, total_items: 0, url: null, skip: true } });
return items;

/* W02 · WordPress post -> raw_items row.
 * Country / funding_type / degree level all come out of this single list call;
 * no per-post request is needed for them. Deadline + eligibility do need the
 * detail page (ACF is empty on this theme), so we flag needs_detail.
 * LIB */
const src = $('Loop Sources').first().json;
const cfg = src.config || {};
const catMap = cfg.category_map || {};

const out = [];
for (const item of $input.all()) {
  const posts = Array.isArray(item.json.body) ? item.json.body
              : Array.isArray(item.json)      ? item.json
              : item.json.id ? [item.json] : [];
  for (const p of posts) {
    if (!p || !p.id) continue;
    const classes = p.class_list || [];
    const tag = (prefix) => classes
      .filter(c => c.startsWith(prefix))
      .map(c => c.slice(prefix.length).replace(/-/g, ' ').trim())
      .filter(Boolean);

    const cats    = p.categories || [];
    const mapped  = cats.map(c => catMap[String(c)]).filter(Boolean);
    const levels  = [...new Set(mapped.flatMap(m => m.levels || []))];
    const urgency = (p.di_urgency || [])[0] || null;

    const y = p.yoast_head_json || {};
    const payload = {
      external_id: String(p.id),
      url: p.link,
      slug: p.slug,
      title: plain((p.title || {}).rendered || y.og_title || ''),
      summary: plain((p.excerpt || {}).rendered || y.og_description || y.description || ''),
      body_html: ((p.content || {}).content || (p.content || {}).rendered || ''),
      image_url: p.jetpack_featured_media_url || ((y.og_image || [])[0] || {}).url || null,
      country_hint: tag('country-')[0] || null,
      funding_hint: tag('funding_type-')[0] || null,
      category_ids: cats,
      type_hint: (mapped[0] || {}).type || null,
      level_hints: levels,
      urgency_term: urgency,
      source_says_expired:   urgency === cfg.expired_urgency_term,
      source_says_no_deadline: urgency === cfg.no_deadline_urgency_term,
      source_published_at: p.date_gmt ? p.date_gmt + 'Z' : null,
      source_modified_at:  p.modified_gmt ? p.modified_gmt + 'Z' : null,
    };

    // The site's own "Expired" bucket is authoritative and free — don't spend a
    // detail fetch on 1100+ dead posts.
    const skipDetail = payload.source_says_expired;

    out.push({ json: {
      source_slug: src.slug,
      external_id: payload.external_id,
      url: payload.url,
      payload,
      content_hash: fingerprint(payload.title + payload.summary, payload.country_hint, payload.source_modified_at),
      needs_detail: Boolean(cfg.needs_detail) && !skipDetail,
      last_seen_at: new Date().toISOString(),
    }});
  }
}
return out;
